//! The Programs module ABI versions the kernel allocates for its receipts.
//!
//! The table and the four named versions are generated by the crate build
//! script from the `LX_PROGRAMS_*ABI_VERSION` enumerators of
//! `include/layerx/programs.h`. Those are the versions the module registers at
//! in `registration.c` of the kernel's Programs module, and the versions
//! `lxp_kernel_prepare_activity` in `src/protocol/lxp_kernel.c` copies out of
//! the matching registration into a receipt's module version, so nothing here
//! holds a second hand-written module ABI number.

include!(concat!(env!("OUT_DIR"), "/programs_module_abi.rs"));

/// Reports whether the kernel header allocates `version` as a Programs module
/// ABI version.
///
/// The kernel registers no zero version and none above [`CURRENT`], the version
/// the module registers at now.
#[must_use]
pub const fn supported(version: u32) -> bool {
    version != 0 && version <= CURRENT
}

#[cfg(test)]
mod tests {
    use super::{supported, ACCOUNT, CURRENT, INITIAL, SANDBOX, SANDBOX_DESTROY, VERSIONS};

    const PROGRAMS_HEADER: &str = include_str!("../../../../include/layerx/programs.h");

    fn header_module_abi_versions() -> Vec<(String, u32)> {
        let mut versions = Vec::new();
        for raw in PROGRAMS_HEADER.lines() {
            let line = raw.trim();
            let Some(rest) = line.strip_prefix("LX_PROGRAMS_") else {
                continue;
            };
            let Some((suffix, value)) = rest.split_once(" = ") else {
                continue;
            };
            if !suffix.ends_with("ABI_VERSION") {
                continue;
            }
            let value: u32 = value
                .trim_end_matches(',')
                .trim()
                .parse()
                .unwrap_or_else(|error| panic!("invalid module ABI number in {line}: {error}"));
            versions.push((format!("LX_PROGRAMS_{suffix}"), value));
        }
        assert!(
            !versions.is_empty(),
            "include/layerx/programs.h declares no Programs module ABI version"
        );
        versions
    }

    #[test]
    fn versions_mirror_the_kernel_headers_programs_module_abi_enumerators() {
        let declared = header_module_abi_versions();
        assert_eq!(declared.len(), VERSIONS.len());
        for ((name, value), (mirrored, version)) in declared.iter().zip(VERSIONS.iter()) {
            assert_eq!(name.as_str(), *mirrored, "{name}");
            assert_eq!(*value, *version, "{name}");
        }
        for (index, (name, version)) in VERSIONS.iter().enumerate() {
            let expected = u32::try_from(index + 1).unwrap_or_else(|error| panic!("{error}"));
            assert_eq!(*version, expected, "{name}");
        }
    }

    #[test]
    fn the_named_versions_are_the_headers_own_and_ascend_to_the_registered_one() {
        let declared = header_module_abi_versions();
        for (name, version) in [
            ("LX_PROGRAMS_ABI_VERSION", INITIAL),
            ("LX_PROGRAMS_ACCOUNT_ABI_VERSION", ACCOUNT),
            ("LX_PROGRAMS_SANDBOX_ABI_VERSION", SANDBOX),
            ("LX_PROGRAMS_SANDBOX_DESTROY_ABI_VERSION", SANDBOX_DESTROY),
        ] {
            let (_, value) = declared
                .iter()
                .find(|(declared, _)| declared == name)
                .unwrap_or_else(|| panic!("{name} is not declared"));
            assert_eq!(*value, version, "{name}");
        }
        assert!(INITIAL < ACCOUNT);
        assert!(ACCOUNT < SANDBOX);
        assert!(SANDBOX < SANDBOX_DESTROY);
        assert_eq!(CURRENT, SANDBOX_DESTROY);
        assert_eq!(
            declared
                .iter()
                .map(|(_, version)| *version)
                .max()
                .unwrap_or_else(|| panic!("no version")),
            CURRENT
        );
    }

    #[test]
    fn supported_admits_exactly_the_allocated_versions() {
        assert!(!supported(0));
        for (name, version) in VERSIONS {
            assert!(supported(version), "{name}");
        }
        for version in 1..=CURRENT {
            assert!(supported(version), "{version}");
        }
        assert!(!supported(CURRENT + 1));
        assert!(!supported(u32::MAX));
    }
}
